  function genScene(id) {
    const m = /^gen:(\w+):(\w+)$/.exec(String(id));
    const kind = KINDS.find((k) => k.id === (m ? m[1] : "")) || pick(KINDS);
    const ctx = kind.ctx.find((c) => c.id === (m ? m[2] : "")) || pick(kind.ctx);
    const sc = kind.build(ctx);
    return Object.assign(sc, { id: `gen:${kind.id}:${ctx.id}`, gen: true, cat: "Generadas", level: kind.level, lesson: kind.lesson });
  }

