  /* ================= ENTONACIÓN ================= */
  const INTO = [
    { id: "yn", name: "Preguntas de sí o no", pat: "rise", rule: "En las preguntas que se responden con sí o no, la voz sube al final.", items: [["Are you coming?", "¿Venís?"], ["Do you like it?", "¿Te gusta?"], ["Is this seat free?", "¿Está libre este asiento?"], ["Can you help me?", "¿Me ayudás?"], ["Have you finished?", "¿Terminaste?"], ["Is it far from here?", "¿Queda lejos?"]] },
    { id: "wh", name: "Preguntas con what, where, how", pat: "fall", rule: "En las preguntas con what, where, when, why o how, la voz baja al final. Si la subís, suena a duda o a sorpresa.", items: [["Where do you live?", "¿Dónde vivís?"], ["What time is it?", "¿Qué hora es?"], ["How much is it?", "¿Cuánto sale?"], ["Why did you call?", "¿Por qué llamaste?"], ["What do you do?", "¿A qué te dedicás?"], ["When does it start?", "¿Cuándo empieza?"]] },
    { id: "st", name: "Afirmaciones", pat: "fall", rule: "En una afirmación, la voz baja al final. Si queda arriba, parece que no terminaste o que estás preguntando.", items: [["I live in Buenos Aires.", "Vivo en Buenos Aires."], ["It's on the second floor.", "Está en el segundo piso."], ["I'd like a coffee, please.", "Quisiera un café, por favor."], ["We launched it on Monday.", "Lo lanzamos el lunes."], ["I work in communications.", "Trabajo en comunicación."], ["That's a good idea.", "Es una buena idea."]] },
    { id: "or", name: "Opciones y listas", pat: "fall", rule: "En las opciones y las listas, la voz sube en cada elemento y baja en el último: tea ↗ or coffee ↘.", items: [["Tea or coffee?", "¿Té o café?"], ["Do you want to walk or take a taxi?", "¿Querés caminar o tomar un taxi?"], ["I need eggs, milk and bread.", "Necesito huevos, leche y pan."], ["Cash or card?", "¿Efectivo o tarjeta?"], ["We have yoga, spinning and boxing.", "Tenemos yoga, spinning y boxeo."]] },
    { id: "echo", name: "Sorpresa y pedir que repitan", pat: "rise", rule: "Para mostrar sorpresa o pedir que te repitan, la voz sube mucho al final.", items: [["Really?", "¿En serio?"], ["Sorry?", "¿Perdón?"], ["Tomorrow?", "¿Mañana?"], ["You did what?", "¿Que hiciste qué?"], ["Are you sure?", "¿Estás seguro?"]] }
  ];

  /* ================= HABLA CONECTADA ================= */
  const E = (en, how, es) => ({ en, how, es });
  const CS = [
    { id: "link", title: "Unir palabras", sub: "an apple suena «a-napple»", why: "En inglés las palabras no se dicen separadas. Cuando una termina en consonante y la siguiente empieza con vocal, se pegan como si fueran una sola. Por eso cuesta entender: no hay silencios entre palabras.",
      ex: [E("an apple", "a-nápel", "una manzana"), E("turn off", "tér-nof", "apagar"), E("pick it up", "pí-ki-tap", "levantalo"), E("not at all", "no-ta-tól", "para nada"), E("what is it?", "uó-tí-zit", "¿qué es?"), E("I need a lot of it", "ai ní-da ló-to-vit", "necesito mucho")],
      say: ["Can I have an apple?", "Turn it off, please.", "Not at all.", "I'll pick it up at eight."] },
    { id: "weak", title: "Palabras débiles", sub: "to, for, of, and casi no se oyen", why: "Las palabras chicas (to, for, of, and, a, the, can) se dicen rápido y con la vocal relajada. Si las pronunciás fuertes y completas, sonás robótico y perdés el ritmo.",
      ex: [E("I want to go", "ai uón-te góu", "to suena «te»"), E("a cup of tea", "a cá-pe tí", "of suena «e»"), E("this is for you", "dí-sis fer iú", "for suena «fer»"), E("fish and chips", "fí-shen chips", "and suena «en»"), E("I can do it", "ai ken dú-it", "can suena «ken»"), E("What are you doing?", "uó-ter iu dú-in", "are suena «er»")],
      say: ["I want to go to the park.", "A cup of tea for you and me.", "I can do it tomorrow.", "What are you doing at the weekend?"] },
    { id: "contr", title: "Contracciones", sub: "I'm, I'll, I'd, don't, won't", why: "Al hablar, casi siempre se contrae. «I will go» suena formal o enfático; lo natural es «I'll go». Y hay que oírlas: «I'd like» no es lo mismo que «I like».",
      ex: [E("I'm", "aim", "I am"), E("I'll", "ail", "I will"), E("I'd", "aid", "I would / I had"), E("we're", "uír", "we are"), E("they've", "déiv", "they have"), E("don't", "dóunt", "do not"), E("won't", "uóunt", "will not"), E("it's", "its", "it is")],
      say: ["I'm sure they'll come.", "I'd like to, but I can't.", "We're late, aren't we?", "It won't take long."],
      ear: "contr" },
    { id: "reduce", title: "Gonna, wanna, gotta", sub: "Las formas rápidas del habla diaria", why: "En series, canciones y charlas vas a oír estas formas todo el tiempo. No se escriben en textos formales, pero hay que entenderlas. Podés usarlas con amigos.",
      ex: [E("going to → gonna", "gó-na", "I'm gonna call you: te voy a llamar"), E("want to → wanna", "uó-na", "I wanna go: quiero ir"), E("got to → gotta", "gó-ra", "I gotta go: me tengo que ir"), E("let me → lemme", "lé-mi", "Lemme see: a ver"), E("give me → gimme", "guí-mi", "Gimme a second: dame un segundo"), E("don't know → dunno", "da-nóu", "I dunno: no sé"), E("kind of → kinda", "cái-na", "It's kinda cold: hace un poco de frío"), E("What do you → Whaddaya", "uó-da-ia", "Whaddaya think?: ¿qué te parece?")],
      say: ["I'm gonna call you later.", "Do you wanna come?", "I gotta go now.", "Lemme think about it."] },
    { id: "flap", title: "La t americana", sub: "water suena «uó-der»", why: "En Estados Unidos, una t entre dos vocales suena como nuestra r suave de «cara». Y después de n, muchas veces desaparece. Si esperás una t fuerte, no reconocés la palabra.",
      ex: [E("water", "uó-rer", "agua"), E("better", "bé-rer", "mejor"), E("city", "sí-ri", "ciudad"), E("a lot of", "a ló-rav", "mucho"), E("internet", "í-ner-net", "la t casi no suena"), E("twenty", "tué-ni", "veinte"), E("What a day!", "uó-ra déi", "¡qué día!")],
      say: ["Can I get a bottle of water?", "It's getting better and better.", "I've got a lot of meetings.", "Twenty minutes in the city."] },
    { id: "cant", title: "Can y can't", sub: "La diferencia casi no es la t", why: "En «I can go», can es débil y rápido («ken») y la fuerza va en go. En «I can't go», can't es fuerte y largo, aunque la t casi no se oiga. La pista es la fuerza de la palabra, no la t.",
      ex: [E("I can GO", "ai ken góu", "can débil, go fuerte"), E("I CAN'T go", "ai cáant gou", "can't fuerte y largo"), E("She can SWIM", "shi ken suím", "puede nadar"), E("She CAN'T swim", "shi cáant suim", "no puede nadar")],
      say: ["I can do it.", "I can't do it.", "You can park here.", "You can't park here."],
      ear: "cant" },
    { id: "send", title: "La -s final", sub: "Tres sonidos: s, z, iz", why: "La s del plural y de la tercera persona suena de tres formas. Después de p, t, k, f suena s (cats). Después de vocales y sonidos con voz suena z (dogs). Después de s, z, sh, ch, x se agrega una sílaba: iz (buses).",
      ex: [E("cats · books · stops", "s", "suena s"), E("dogs · days · runs", "z", "suena z, vibra"), E("buses · watches · boxes", "iz", "suma una sílaba"), E("He works", "uérks", "s"), E("She plays", "pléiz", "z"), E("It finishes", "fí-ni-shiz", "iz")],
      say: ["She works and plays.", "He watches the news.", "Two buses and three taxis.", "It changes every day."] },
    { id: "rhythm", title: "El ritmo de la frase", sub: "Fuertes las palabras que importan", why: "En español cada sílaba dura parecido. En inglés no: las palabras con contenido (sustantivos, verbos, adjetivos) van fuertes y largas, y las chicas se comprimen entre medio. Ese sube y baja es el ritmo del inglés.",
      ex: [E("I WANT to GO to the PARK", "tres golpes", "want, go, park"), E("She BOUGHT a NEW CAR", "tres golpes", "bought, new, car"), E("Can you TELL me the TIME?", "dos golpes", "tell, time"), E("I'm GOing to the OFfice at NINE", "tres golpes", "going, office, nine")],
      say: ["I want to go to the park.", "She bought a new car.", "Can you tell me the time?", "I'm going to the office at nine."] }
  ];
  const EARX = {
    cant: { title: "Can o can't", error: "En «can» la fuerza va en el verbo que sigue; en «can't» la fuerza va en can't, que suena más largo.", pairs: [["I can do it.", "I can't do it."], ["You can park here.", "You can't park here."], ["She can come.", "She can't come."], ["We can see it.", "We can't see it."], ["He can swim.", "He can't swim."], ["I can hear you.", "I can't hear you."]] },
    teens: { title: "Thirteen o thirty", error: "En thirteen, fourteen… la fuerza va al final (-TEEN). En thirty, forty… va al principio y termina en -ty corto.", pairs: [["thirteen", "thirty"], ["fourteen", "forty"], ["fifteen", "fifty"], ["sixteen", "sixty"], ["seventeen", "seventy"], ["eighteen", "eighty"], ["nineteen", "ninety"]] },
    contr: { title: "Con o sin contracción", error: "La contracción es un sonido cortito pegado a la palabra: I'll suena «ail», I'd suena «aid».", pairs: [["I walk to work.", "I'll walk to work."], ["I like it.", "I'd like it."], ["They go home.", "They'll go home."], ["We were late.", "We're late."], ["He is here.", "He was here."], ["I want to go.", "I won't go."]] },
    similar: { title: "Palabras que se confunden", error: "Son palabras distintas que para nuestro oído suenan casi igual. La diferencia suele estar en la vocal.", pairs: [["walk", "work"], ["want", "won't"], ["this", "these"], ["beer", "bear"], ["hear", "hair"], ["quite", "quiet"], ["word", "world"], ["tree", "three"], ["sheet", "seat"], ["cap", "cup"], ["hat", "hot"], ["bird", "beard"]] }
  };
